CREATE OR REPLACE FUNCTION public.validate_lead_data()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    -- Validate Full Name
    IF NEW.full_name IS NULL OR length(trim(NEW.full_name)) < 3 THEN
        RAISE EXCEPTION 'Nome completo inválido. Deve ter pelo menos 3 caracteres.';
    END IF;

    -- Validate Email
    IF NEW.email IS NULL OR NEW.email !~* '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' THEN
        RAISE EXCEPTION 'E-mail inválido.';
    END IF;

    -- Validate Phone
    IF NEW.phone IS NULL OR length(regexp_replace(NEW.phone, '\D', '', 'g')) < 10 THEN
        RAISE EXCEPTION 'Telefone inválido. Informe o DDD e o número completo.';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_referral_data()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.referred_name IS NULL OR length(trim(NEW.referred_name)) < 3 THEN
    RAISE EXCEPTION 'Nome do indicado inválido (mínimo 3 caracteres).';
  END IF;
  IF NEW.referrer_name IS NULL OR length(trim(NEW.referrer_name)) < 3 THEN
    RAISE EXCEPTION 'Seu nome é obrigatório (mínimo 3 caracteres).';
  END IF;
  IF NEW.referrer_email IS NULL OR NEW.referrer_email !~* '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' THEN
    RAISE EXCEPTION 'E-mail do indicador inválido.';
  END IF;
  IF NEW.referred_phone IS NOT NULL AND length(regexp_replace(NEW.referred_phone, '\D', '', 'g')) < 10 THEN
    RAISE EXCEPTION 'Telefone do indicado inválido.';
  END IF;
  RETURN NEW;
END;
$function$
